class Solution {
    public long maximumSum(List<Integer> nums) {
        int n = nums.size();
        long ans = 0;
        for (int c = 1; c <= n; c++) {
            long curr = 0;
            for (int d = 1; (long) c * d * d <= n; d++) {
                curr += nums.get(c * d * d - 1);
            }
            ans = Math.max(ans, curr);
        }
        return ans;
    }
}

